// План specs/admin-coupons.md 2.4 (кейс CP-08). Admin, десктоп, EN. @prod-safe: форма New coupon только заполняется, Save НЕ нажимается.
import { test, expect } from '../../fixtures';
import {
  DATE_ERROR_EN,
  blockCouponWrites, browserDate, cancelDialog, expectNoCouponWrites, openCoupons, openNewCouponFilled, restoreTest, saveButton, startInTest,
} from './coupon-helpers';

test('New coupon: "Expires on" cannot be earlier than today — min = today, yesterday shows "Pick today or a later date." and Save is disabled (not saved) #b93722 @desktop @prod-safe', async ({ asUser }) => {
  const page = await asUser('admin');
  await startInTest(page);
  const writes = await blockCouponWrites(page);
  try {
    await openCoupons(page);
    const dlg = await openNewCouponFilled(page);
    const expires = dlg.getByLabel(/Expires on/);
    const today = await browserDate(page, 0);
    // Источник: описание #b93722 п.1 (תאריך תפוגה), ручная проверка 18–19.10: в календаре нельзя выбрать прошлое.
    await expect(expires).toHaveAttribute('min', today);

    await expires.fill(await browserDate(page, -1));
    await expires.blur();
    await expect(dlg.getByText(DATE_ERROR_EN, { exact: true })).toBeVisible();
    await expect(saveButton(dlg)).toBeDisabled();

    await expires.fill(today);
    await expires.blur();
    await expect(dlg.getByText(DATE_ERROR_EN, { exact: true })).toBeHidden();
    await expect(saveButton(dlg)).toBeEnabled();
    await cancelDialog(page);
  } finally {
    await restoreTest(page);
  }
  expectNoCouponWrites(writes);
});
